package library_loan_service.loan_db;

import com.zaxxer.hikari.HikariConfig;
import com.zaxxer.hikari.HikariDataSource;
import javax.sql.DataSource;
import library_loan_service.config.RemoteConfig;
import library_loan_service.security.SecretsResolver;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * HikariCP {@code DataSource} configuration for the 'loanDb' RDBMS block (postgres). Every RDBMS
 * block gets its own explicitly-named bean -- no {@code @Primary} guess across multi-block
 * services.
 *
 * <p>Auto-generated by datrix-codegen-java. Do not edit manually.
 */
@Configuration
public class LoanDbDataSourceConfig {

  @Bean(name = "loan_dbDataSource")
  public DataSource loan_dbDataSource(RemoteConfig remoteConfig, SecretsResolver secretsResolver) {
    String host = remoteConfig.getLoanDbHost();
    int port = remoteConfig.getLoanDbPort();
    String database = remoteConfig.getLoanDbDatabase();
    String username = remoteConfig.getLoanDbUser();

    String jdbcUrl = "jdbc:postgresql://" + host + ":" + port + "/" + database;

    HikariConfig hikariConfig = new HikariConfig();
    hikariConfig.setJdbcUrl(jdbcUrl);
    hikariConfig.setDriverClassName("org.postgresql.Driver");
    hikariConfig.setUsername(username);
    hikariConfig.setPassword(secretsResolver.getSecret("loan_db_password"));
    hikariConfig.setMaximumPoolSize(20);

    return new HikariDataSource(hikariConfig);
  }
}
